import { _decorator, Button, Component, Label, Node } from 'cc';
import type { StoryChoiceOption, StoryChoiceScript, StoryDialogueScript } from './StoryMapTypes';
import { StoryUIViewRefs } from './StoryUIViewRefs';

const { ccclass, property } = _decorator;

function childByPath(root: Node | null, segments: string[]): Node | null {
    let cur: Node | null = root;
    for (let i = 0; i < segments.length; i++) {
        if (!cur) return null;
        cur = cur.getChildByName(segments[i]);
    }
    return cur;
}

/**
 * 驱动 Story UI：对白、选项、Toast、交互提示。
 * 建议挂在 CanvasRoot(UI)，与 StoryUIViewRefs 同节点；节点路径与 StoryUIAutoBuilder 一致。
 *
 * 编辑器绑定（可选）：StoryUIViewRefs 拖引用；留空则在运行时按层级名解析。
 */
@ccclass('StoryUIViewController')
export class StoryUIViewController extends Component {
    @property({ type: StoryUIViewRefs, tooltip: '留空则从本节点 getComponent' })
    viewRefs: StoryUIViewRefs | null = null;

    private _refsResolved = false;

    private _storyLayer: Node | null = null;
    private _dialoguePanel: Node | null = null;
    private _speakerLabel: Label | null = null;
    private _bodyLabel: Label | null = null;
    private _nextBtn: Button | null = null;
    private _closeBtn: Button | null = null;

    private _choiceModal: Node | null = null;
    private _choiceTitle: Label | null = null;
    private _choiceBtnNodes: Node[] = [];
    private _choiceButtons: Button[] = [];
    private _choiceLabels: Label[] = [];
    private _subReplyArea: Node | null = null;
    private _subReplyLabel: Label | null = null;

    private _toastRoot: Node | null = null;
    private _toastLabel: Label | null = null;

    private _interactPrompt: Node | null = null;
    private _interactPromptLabel: Label | null = null;

    private _dlgLines: string[] = [];
    private _dlgIdx = 0;
    private _onDialogueEnd: ((cancelled: boolean) => void) | null = null;

    private _runningChoice: StoryChoiceScript | null = null;
    private _choiceDone: ((opt: StoryChoiceOption) => void) | null = null;
    private _choiceClosing = false;

    start() {
        this.scheduleOnce(() => this.ensureRefs(), 0);
    }

    ensureRefs(): void {
        if (this._refsResolved) return;
        const vr = this.viewRefs ?? this.getComponent(StoryUIViewRefs);
        this.viewRefs = vr;

        const root = this.node;
        this._storyLayer = childByPath(root, ['StoryLayer']);

        this._dialoguePanel = vr?.dialoguePanel ?? childByPath(this._storyLayer, ['DialoguePanel']);
        const dlg = this._dialoguePanel;
        const spkNode = vr?.dialogueSpeakerLabel ?? childByPath(dlg, ['SpeakerNameLabel']);
        const bodyNode = vr?.dialogueTextLabel ?? childByPath(dlg, ['LinesContainer', 'Text']);
        this._speakerLabel = spkNode?.getComponent(Label) ?? null;
        this._bodyLabel = bodyNode?.getComponent(Label) ?? null;

        const nextNd = vr?.nextButton ?? childByPath(dlg, ['NextBtn']);
        this._nextBtn = nextNd?.getComponent(Button) ?? null;
        const closeNd = childByPath(dlg, ['CloseBtn']);
        this._closeBtn = closeNd?.getComponent(Button) ?? null;

        this._choiceModal = vr?.choiceModal ?? childByPath(this._storyLayer, ['ChoiceModal']);
        const cm = this._choiceModal;
        const titleNd = vr?.choiceTitleLabel ?? childByPath(cm, ['TitleLabel']);
        this._choiceTitle = titleNd?.getComponent(Label) ?? null;

        const optRoot = childByPath(cm, ['OptionsContainer']);
        this._choiceBtnNodes = [];
        this._choiceButtons = [];
        this._choiceLabels = [];
        if (optRoot) {
            const ch = optRoot.children ?? [];
            const opts = ch.filter((n) => n.name.startsWith('OptionButton'));
            opts.sort((a, b) => a.name.localeCompare(b.name));
            for (let i = 0; i < opts.length; i++) {
                const bn = opts[i];
                this._choiceBtnNodes.push(bn);
                this._choiceButtons.push(bn.getComponent(Button) ?? bn.addComponent(Button));
                const tn = bn.getChildByName('Text');
                this._choiceLabels.push(tn?.getComponent(Label) ?? bn.getComponent(Label) ?? bn.addComponent(Label));
            }
        }
        if (vr?.choiceButtons?.length) {
            for (let i = 0; i < vr.choiceButtons.length; i++) {
                const bn = vr.choiceButtons[i];
                if (!bn || this._choiceBtnNodes.includes(bn)) continue;
                this._choiceBtnNodes.push(bn);
                this._choiceButtons.push(bn.getComponent(Button) ?? bn.addComponent(Button));
                const tn = bn.getChildByName('Text');
                this._choiceLabels.push(tn?.getComponent(Label) ?? bn.getComponent(Label) ?? bn.addComponent(Label));
            }
        }

        this._subReplyArea = childByPath(cm, ['SubReplyArea']);
        const replyTextNd = childByPath(this._subReplyArea, ['Text']);
        this._subReplyLabel = replyTextNd?.getComponent(Label) ?? null;

        const toastNd = vr?.toastItem ?? childByPath(this._storyLayer, ['SystemTipLayer', 'ToastItem']);
        this._toastRoot = toastNd;
        const toastTextNd = vr?.toastTextLabel ?? childByPath(toastNd, ['Text']);
        this._toastLabel = toastTextNd?.getComponent(Label) ?? null;

        const promptNd = vr?.interactPrompt ?? childByPath(root, ['HUDLayer', 'InteractPrompt']);
        this._interactPrompt = promptNd;
        const promptTextNd = vr?.interactPromptText ?? childByPath(promptNd, ['PromptText']);
        this._interactPromptLabel = promptTextNd?.getComponent(Label) ?? null;

        this._wireButtons();
        this._refsResolved = true;
    }

    private _wireButtons(): void {
        this._nextBtn?.node?.off(Button.EventType.CLICK);
        this._nextBtn?.node?.on(Button.EventType.CLICK, this._onNextDialogue, this);
        this._closeBtn?.node?.off(Button.EventType.CLICK);
        this._closeBtn?.node?.on(Button.EventType.CLICK, this._onCloseDialogue, this);
        for (let i = 0; i < this._choiceButtons.length; i++) {
            const idx = i;
            const b = this._choiceButtons[i];
            b.node.off(Button.EventType.CLICK);
            b.node.on(Button.EventType.CLICK, () => this._onPickChoice(idx), this);
        }
    }

    onDestroy(): void {
        this.unscheduleAllCallbacks();
        this._nextBtn?.node?.off(Button.EventType.CLICK, this._onNextDialogue, this);
        this._closeBtn?.node?.off(Button.EventType.CLICK, this._onCloseDialogue, this);
        for (let i = 0; i < this._choiceButtons.length; i++) {
            this._choiceButtons[i].node.targetOff(this);
        }
    }

    isBlockingInput(): boolean {
        if (!this._refsResolved) return false;
        if (this._dialoguePanel?.active) return true;
        if (this._choiceModal?.active) return true;
        return false;
    }

    showInteractPrompt(visible: boolean, text = '按 E 对话'): void {
        this.ensureRefs();
        if (this._interactPrompt) this._interactPrompt.active = visible;
        if (this._interactPromptLabel) this._interactPromptLabel.string = text;
    }

    showToast(message: string, durationSec = 2.2): void {
        this.ensureRefs();
        if (!this._toastRoot || !this._toastLabel) {
            console.warn('[StoryUIViewController] Toast 节点未就绪:', message);
            return;
        }
        this.unschedule(this._hideToast);
        this._toastLabel.string = message;
        this._toastRoot.active = true;
        this.scheduleOnce(this._hideToast, durationSec);
    }

    private _hideToast = (): void => {
        if (this._toastRoot?.isValid) this._toastRoot.active = false;
    };

    runDialogue(script: StoryDialogueScript, onEnd: (cancelled: boolean) => void): void {
        this.ensureRefs();
        this._onDialogueEnd = onEnd;
        this._dlgLines = script.lines ?? [];
        this._dlgIdx = 0;
        if (this._closeBtn?.node) this._closeBtn.node.active = true;
        if (this._dialoguePanel) this._dialoguePanel.active = true;
        if (this._speakerLabel) this._speakerLabel.string = script.speaker ?? '';
        this._refreshDialogueLine();
    }

    private _refreshDialogueLine(): void {
        const line = this._dlgLines[this._dlgIdx] ?? '';
        if (this._bodyLabel) this._bodyLabel.string = line;
    }

    private _onNextDialogue(): void {
        if (this._dlgIdx + 1 < this._dlgLines.length) {
            this._dlgIdx++;
            this._refreshDialogueLine();
            return;
        }
        this._finishDialogue(false);
    }

    private _onCloseDialogue(): void {
        this._finishDialogue(true);
    }

    private _finishDialogue(cancelled: boolean): void {
        if (this._dialoguePanel?.isValid) this._dialoguePanel.active = false;
        const cb = this._onDialogueEnd;
        this._onDialogueEnd = null;
        if (cb) cb(cancelled);
    }

    runChoice(script: StoryChoiceScript, onPick: (option: StoryChoiceOption) => void): void {
        this.ensureRefs();
        this._runningChoice = script;
        this._choiceDone = onPick;
        this._choiceClosing = false;
        const opts = script.options ?? [];
        if (!this._choiceModal) {
            if (opts[0]) onPick(opts[0]);
            else onPick({ id: '_empty', text: '' });
            this._runningChoice = null;
            return;
        }
        if (this._choiceTitle) this._choiceTitle.string = script.title ?? '';
        for (let i = 0; i < this._choiceBtnNodes.length; i++) {
            const show = i < opts.length;
            this._choiceBtnNodes[i].active = show;
            if (show && this._choiceLabels[i]) this._choiceLabels[i].string = opts[i].text ?? '';
        }
        if (this._subReplyArea) this._subReplyArea.active = false;
        this._choiceModal.active = true;
    }

    private _closeChoiceModal(): void {
        if (this._choiceModal?.isValid) this._choiceModal.active = false;
        this._runningChoice = null;
        this._choiceDone = null;
        this._choiceClosing = false;
    }

    private _onPickChoice(btnIndex: number): void {
        if (this._choiceClosing) return;
        const cb = this._choiceDone;
        const script = this._runningChoice;
        if (!cb || !script || !this._choiceModal?.active) return;
        if (!this._choiceBtnNodes[btnIndex]?.active) return;

        const opts = script.options ?? [];
        const picked = opts[btnIndex];
        if (!picked) return;

        this._choiceClosing = true;
        for (let i = 0; i < this._choiceButtons.length; i++) {
            this._choiceButtons[i].interactable = false;
        }

        const finish = () => {
            for (let i = 0; i < this._choiceButtons.length; i++) {
                this._choiceButtons[i].interactable = true;
            }
            const fn = cb;
            this._closeChoiceModal();
            fn(picked);
        };

        const reply = picked.npcReply?.trim() ?? '';
        if (reply.length > 0 && this._subReplyArea && this._subReplyLabel) {
            this._subReplyLabel.string = reply;
            this._subReplyArea.active = true;
            for (let i = 0; i < this._choiceBtnNodes.length; i++) {
                this._choiceBtnNodes[i].active = false;
            }
            this.scheduleOnce(() => finish(), 2.0);
        } else {
            finish();
        }
    }
}
